// clone deep-copies decoded JSON so ForAPI output never aliases the stored schema.
func clone(v any) any {
	switch t := v.(type) {
	case map[string]any:
		m := make(map[string]any, len(t))
		for k, val := range t {
			m[k] = clone(val)
		}
		return m
	case []any:
		l := make([]any, len(t))
		for i, val := range t {
			l[i] = clone(val)
		}
		return l
	default:
		return v
	}
}

