		api, err := s.ForAPI(name)
		if err != nil {
			t.Fatalf("ForAPI(%s): %v", name, err)
		}
		walk(api, string(name), func(path string, m map[string]any) {
			for k, v := range m {
				if unsupportedForAPI[k] {
