	s := mustLoad(t)
	api, err := s.ForAPI(SegmentRule)
	if err != nil {
		t.Fatal(err)
	}
	city := api["$defs"].(map[string]any)["city"].(map[string]any)
	city["enum"] = append(city["enum"].([]any), "paris")
	city["enum"].([]any)[0] = "paris"

