		cond := Condition{Kind: cm["kind"].(string)}
		switch cond.Kind {
		case KindEnum:
			cond.Field, cond.Op = cm["field"].(string), cm["op"].(string)
			if list, ok := cm["value"].([]any); ok {
				for _, item := range list {
