	want := Rule{Match: "all", Conditions: []Condition{
		{Kind: KindEnum, Field: "city", Op: "eq", Value: "istanbul"},
		{Kind: KindEvent, Event: "cart_add", WithinDays: 30},
		{Kind: KindEvent, Event: "purchase", WithinDays: 30, Negate: true},
