	want := Rule{Match: "any", Conditions: []Condition{
		{Kind: KindEnum, Field: "city", Op: "in", Values: []string{"istanbul", "ankara"}},
		{Kind: KindNumber, Field: "days_since_signup", Op: "gte", Number: 30},
