		t.Errorf("schema subject maxLength %d, SubjectMaxChars %d", got, SubjectMaxChars)
	}
}

func TestParse(t *testing.T) {
	parts, issues := Parse("Merhaba {{ first_name }}, {{city}}'da indirim!")
