package store

import (
	"context"
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"errors"
	"net/url"
	"os"
	"regexp"
	"slices"
	"testing"

	"github.com/jackc/pgx/v5/pgconn"
	_ "github.com/jackc/pgx/v5/stdlib"

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/segment"
)

// freshDB creates an empty database for one test and drops it afterwards.
// Step 10 replaces this with internal/testdb (clones of a seeded template).
func freshDB(t *testing.T) *sql.DB {
	t.Helper()
	base := os.Getenv("TEST_DATABASE_URL")
	if base == "" {
		if os.Getenv("REQUIRE_DB") == "1" {
			t.Fatal("REQUIRE_DB=1 but TEST_DATABASE_URL is not set")
		}
		t.Skip("TEST_DATABASE_URL is not set; run the integration tests with make test")
	}
	admin, err := sql.Open("pgx", base)
	if err != nil {
		t.Fatal(err)
	}
	b := make([]byte, 6)
	_, _ = rand.Read(b)
	name := "store_test_" + hex.EncodeToString(b)
	if _, err := admin.Exec("CREATE DATABASE " + name); err != nil {
		t.Fatal(err)
	}
	u, err := url.Parse(base)
	if err != nil {
		t.Fatal(err)
	}
	u.Path = "/" + name
	db, err := sql.Open("pgx", u.String())
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		db.Close()
		if _, err := admin.Exec("DROP DATABASE " + name + " WITH (FORCE)"); err != nil {
			t.Errorf("drop %s: %v", name, err)
		}
		admin.Close()
	})
	return db
}

var appTables = []string{"users", "user_events", "seed_meta", "campaigns", "campaign_revisions", "campaign_events", "llm_calls", "messages"}

func tablesPresent(t *testing.T, db *sql.DB) []string {
	t.Helper()
	var present []string
	for _, tbl := range appTables {
		var ok bool
		if err := db.QueryRow("SELECT to_regclass('public.' || $1) IS NOT NULL", tbl).Scan(&ok); err != nil {
			t.Fatal(err)
		}
		if ok {
			present = append(present, tbl)
		}
	}
	return present
}

func TestMigrateUpDownUp(t *testing.T) {
	ctx := context.Background()
	db := freshDB(t)

	if err := Migrate(ctx, db); err != nil {
		t.Fatal(err)
	}
	if got := tablesPresent(t, db); !slices.Equal(got, appTables) {
		t.Fatalf("after up: tables %v, want %v", got, appTables)
	}
	if err := Migrate(ctx, db); err != nil {
		t.Fatalf("second run is not a no-op: %v", err)
	}
	p, err := newMigrator(db)
	if err != nil {
		t.Fatal(err)
	}
	if v, err := p.GetDBVersion(ctx); err != nil || v != 2 {
		t.Fatalf("version %d, %v; want 2", v, err)
	}

	if _, err := p.DownTo(ctx, 0); err != nil {
