package seed

import (
	"context"
	"fmt"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

// lockID serializes concurrent loaders (two setup runs at once).
const lockID int64 = 0x5eed

// Load writes ds in one transaction and reports whether it wrote anything.
//
// Without reset, existing data is kept: if any user exists, nothing is
// written, so running setup twice is safe. With reset, users, events,
// seed_meta and every campaign (with its revisions, audit events, LLM calls
// and messages) are removed first. That is a dev reset that re-anchors the
// data at ds.AsOf.
func Load(ctx context.Context, pool *pgxpool.Pool, ds Dataset, reset bool) (bool, error) {
	tx, err := pool.Begin(ctx)
	if err != nil {
		return false, err
	}
	defer tx.Rollback(ctx) //nolint:errcheck // no-op after Commit

	if _, err := tx.Exec(ctx, "SELECT pg_advisory_xact_lock($1)", lockID); err != nil {
		return false, err
	}
	if reset {
		if _, err := tx.Exec(ctx, "TRUNCATE users, seed_meta, campaigns CASCADE"); err != nil {
			return false, err
		}
	} else {
		var exists bool
		if err := tx.QueryRow(ctx, "SELECT EXISTS (SELECT 1 FROM users)").Scan(&exists); err != nil {
			return false, err
		}
		if exists {
			return false, nil
		}
	}

	users := pgx.CopyFromSlice(len(ds.Users), func(i int) ([]any, error) {
		u := ds.Users[i]
		return []any{u.ID, u.FirstName, u.LastName, u.Email, u.Phone, u.City, u.Language,
			u.LoyaltyTier, u.SignupAt, u.ConsentSMS, u.ConsentEmail}, nil
	})
	if _, err := tx.CopyFrom(ctx, pgx.Identifier{"users"}, []string{"id", "first_name", "last_name", "email",
		"phone", "city", "language", "loyalty_tier", "signup_at", "consent_sms", "consent_email"}, users); err != nil {
		return false, fmt.Errorf("seed users: %w", err)
	}
	events := pgx.CopyFromSlice(len(ds.Events), func(i int) ([]any, error) {
		e := ds.Events[i]
		return []any{e.UserID, e.Type, e.OccurredAt}, nil
	})
	if _, err := tx.CopyFrom(ctx, pgx.Identifier{"user_events"}, []string{"user_id", "type", "occurred_at"}, events); err != nil {
		return false, fmt.Errorf("seed events: %w", err)
	}
	if _, err := tx.Exec(ctx, "INSERT INTO seed_meta (as_of, seed, user_count) VALUES ($1, $2, $3)",
		ds.AsOf, ds.Seed, len(ds.Users)); err != nil {
		return false, err
	}
	return true, tx.Commit(ctx)
}

// Command app is the single binary for every service. The first argument
// picks the subcommand.
//
//	app migrate                    apply database migrations
//	app seed [-users N] [-seed S] [-as-of now|RFC3339] [-reset]
//	                               load synthetic users and events
//
// Both need DATABASE_URL. More subcommands (api, worker, mockprovider) are
// added as they are built.
package main

import (
	"context"
	"database/sql"
	"errors"
	"flag"
	"fmt"
	"log/slog"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
	_ "github.com/jackc/pgx/v5/stdlib" // registers the "pgx" database/sql driver

	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/seed"
	"github.com/BoraKaraman1/insider_one_smart_composer_case/internal/store"
)

func main() {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()
	log := slog.New(slog.NewJSONHandler(os.Stderr, nil))

	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "usage: app <migrate|seed> [flags]")
		os.Exit(2)
	}
	var err error
	switch os.Args[1] {
	case "migrate":
		err = migrate(ctx)
	case "seed":
		err = seedCmd(ctx, log, os.Args[2:])
	default:
		err = fmt.Errorf("unknown subcommand %q", os.Args[1])
	}
	if err != nil {
		log.Error("failed", "subcommand", os.Args[1], "error", err)
		os.Exit(1)
	}
}

func databaseURL() (string, error) {
	url := os.Getenv("DATABASE_URL")
	if url == "" {
		return "", errors.New("DATABASE_URL is not set")
	}
	return url, nil
}

func migrate(ctx context.Context) error {
	url, err := databaseURL()
	if err != nil {
		return err
	}
	db, err := sql.Open("pgx", url)
	if err != nil {
		return err
	}
	defer db.Close()
	return store.Migrate(ctx, db)
}

func seedCmd(ctx context.Context, log *slog.Logger, args []string) error {
	fs := flag.NewFlagSet("seed", flag.ContinueOnError)
	users := fs.Int("users", 5000, "number of users")
	seedValue := fs.Int64("seed", 42, "random seed")
	asOfFlag := fs.String("as-of", "now", `time anchor: "now" or an RFC 3339 time`)
	reset := fs.Bool("reset", false, "delete users, events and all campaigns first, then reload")
	if err := fs.Parse(args); err != nil {
		return err
	}
	asOf := time.Now()
	if *asOfFlag != "now" {
		var err error
		if asOf, err = time.Parse(time.RFC3339Nano, *asOfFlag); err != nil {
			return fmt.Errorf("-as-of: %w", err)
		}
	}
	ds, err := seed.Generate(*seedValue, asOf, *users)
	if err != nil {
		return err
	}
	url, err := databaseURL()
	if err != nil {
		return err
	}
	pool, err := pgxpool.New(ctx, url)
	if err != nil {
		return err
	}
	defer pool.Close()
	loaded, err := seed.Load(ctx, pool, ds, *reset)
	if err != nil {
		return err
	}
	if !loaded {
		log.Info("seed skipped: users already present (use -reset to reload)")
		return nil
	}
	log.Info("seed loaded", "users", len(ds.Users), "events", len(ds.Events), "seed", ds.Seed, "as_of", ds.AsOf)
	return nil
}

